                    moe_combine(m.Dm, m.slot_dev, m.w, m.shared, m.sg, m.bo, T, m.cs);
                }
                // ---- the hyper-connection write of this half
                gr_write(m.R, m.bo, m.inj, HC, T, m.cs);
            }
